// Ajoute 286 joueurs manquants (367 -> 653), trouves en comparant la base
// actuelle a une longue liste de references : Ballon d'Or et legendes de
// chaque grand championnat europeen depuis 1990, gros travail specifique
// sur la Ligue 1 et la Liga (demande explicite), puis des joueurs plus
// "lambda" (pas que des stars) pour varier la difficulte du quiz. Ajoute
// aussi 12 nouveaux codes de nationalite (NAT_FR dans engine.ts) pour que
// ces joueurs affichent bien leur pays : Autriche, Bosnie, Burkina Faso,
// Bulgarie, Tchequie, Jamaique, Liberia, Mexique, Roumanie, Russie,
// Slovaquie, Tunisie.
//
// Bonus au passage : ADS_LIVE etait reste a true dans le code source (le
// dernier retour a false n'avait jamais ete pousse) - remis a false pour
// de bon, comme decide apres le 3e crash identique.
//
// Les photos, c'est toi qui t'en occupes de ton cote.
// Run from strikr-app/: node patch-add-286-players.js
const fs = require('fs');
const path = require('path');

function write(rel, content) {
  const full = path.join(process.cwd(), rel);
  fs.writeFileSync(full, content);
  console.log('WROTE', rel);
}

